import json
import zipfile
import shutil
import uuid
from pathlib import Path
from typing import List, Dict, Optional, Tuple

from robot.api import logger
from taf.sw.dcap.rd import rd
from taf.converters.emil import emil


class Decoder:
    """
    Decoder class for converting EMIL files to JSON formats.
    """

    def __init__(self):
        """
        Initialize the Decoder with DCAP RD and EMIL converter instances.
        """
        self._dcap_rd = rd()
        self._emil_converter = emil()

    def decode_emil_to_json(self, input_path: str, output_path: str, utf_host: str, utf_port: str = '443',
                            username: Optional[str] = None, password: Optional[str] = None,
                            rd_version: str = 'dcapv3', secure: bool = True) -> str:
        """
        Decode EMIL file to JSON format using DCAP RD.

        :param input_path: The path to the input EMIL file.
        :param output_path: The path to the output JSON file.
        :param utf_host: The UTF host address.
        :param utf_port: The UTF port number.
        :param username: The username for authentication.
        :param password: The password for authentication.
        :param rd_version: The RD version to use.
        :param secure: Whether to use secure connection.

        :return: Path to the output JSON file.
        """
        output_path_obj = Path(output_path)
        output_path_obj.parent.mkdir(parents=True, exist_ok=True)

        logger.debug(f"Connecting to DCAP RD at {utf_host}:{utf_port} (rd_version={rd_version})")
        self._dcap_rd.connect_to(
            host=utf_host,
            port=utf_port,
            rd_version=rd_version,
            secure=secure,
            username=username,
            password=password
        )

        logger.debug(f"Uploading encoded file: {input_path}")
        trace = self._dcap_rd.upload_encoded_file(file_name=input_path)
        result = self._dcap_rd.get_decoded_file_contents_in_json(
            session_id=trace['session_id'],
            data_source_id=trace['source_ids'][0],
            what='source',
            timeout=180)

        json_string = json.dumps(result, ensure_ascii=False)
        with open(output_path, 'w', encoding='utf-8') as json_file:
            json_file.write(json_string)
        logger.debug(f"Decoded EMIL to JSON: {input_path} -> {output_path}")

        return output_path

    def decode_emil_to_ndjson(self, input_path: str, output_path: str, utf_host: str, utf_port: str = '443') -> str:
        """
        Decode EMIL file to NDJSON format using EMIL converter.

        :param input_path: The path to the input EMIL file.
        :param output_path: The path to the output directory for NDJSON file.
        :param utf_host: The UTF host address.
        :param utf_port: The UTF port number.

        :return: Path to the output NDJSON file.
        """
        logger.debug(f"Decoding EMIL to NDJSON: {input_path} -> {output_path}")
        self._decode_emil_with_converter(
            input_path=input_path,
            output_path=output_path,
            utf_host=utf_host,
            utf_port=utf_port,
            converter_name='emil_json'
        )
        logger.debug(f"Decoded EMIL to NDJSON: {output_path}")
        return output_path

    def decode_emil_to_csv(self, input_path: str, output_path: str, utf_host: str, utf_port: str = '443') -> str:
        """
        Decode EMIL file to NDCSV format using EMIL converter.

        :param input_path: The path to the input EMIL file.
        :param output_path: The path to the output directory for NDCSV file.
        :param utf_host: The UTF host address.
        :param utf_port: The UTF port number.

        :return: Path to the output NDCSV file.
        """
        logger.debug(f"Decoding EMIL to CSV: {input_path} -> {output_path}")
        self._decode_emil_with_converter(
            input_path=input_path,
            output_path=output_path,
            utf_host=utf_host,
            utf_port=utf_port,
            converter_name='emil_csv',
            output_type='csv'
        )
        logger.debug(f"Decoded EMIL to CSV: {output_path}")
        return output_path

    def create_emil_json_file_from_utf_zipped_logs(self, utf_logs: str, output_path: str, utf_host: str,
                                                   utf_port: str = '443', json_format: str = 'json',
                                                   clean_temporary_dirs: bool = True,
                                                   file_prefix: str = "emil_logs") -> List[str]:
        """
        Extract .5gm files from UTF zipped logs, decode them to JSON/NDJSON, group by BTS ID and merge per BTS.

        :param utf_logs: Path to ZIP archive containing EMIL (.5gm) logs downloaded from UTF.
        :param output_path: Path to the output directory; merged files merged_{bts_id}.json will be created inside it.
        :param utf_host: The UTF host address.
        :param utf_port: The UTF port number.
        :param json_format: Output format: 'json' or 'ndjson'.
        :param clean_temporary_dirs: Whether to clean temporary directories after processing.
        :param file_prefix: Prefix for the output merged files.

        :return: List of paths to merged output files (one per BTS ID).
        """
        logger.debug(f"Creating EMIL JSON from UTF zipped logs: {utf_logs} -> {output_path} (format: {json_format})")
        output_path_obj, emil_5gm_files_dir, emil_json_files_dir = self._ensure_directories_for_utf_zipped_logs(
            output_path
        )

        emil_5gm_files = self.extract_5gm_files_from_zip(utf_logs, str(emil_5gm_files_dir))
        emil_json_files = self._decode_5gm_files_to_json(
            emil_5gm_files, emil_json_files_dir, utf_host, utf_port, json_format
        )

        json_files_by_bts_id = self.sort_emil_log_files(emil_json_files)
        merged_files = self._merge_json_by_bts_id(
            json_files_by_bts_id, output_path_obj, file_prefix, json_format
        )

        if clean_temporary_dirs:
            self._remove_temporary_directories(emil_5gm_files_dir, emil_json_files_dir)

        return merged_files

    @staticmethod
    def extract_5gm_files_from_zip(zip_path: str, output_dir: str) -> List[str]:
        """
        Extract all files with .5gm extension from a ZIP archive.
        Files are extracted directly to the output directory without preserving folder structure.

        :param zip_path: The path to the ZIP file.
        :param output_dir: The directory where extracted files will be saved.

        :return: List of paths to extracted files.

        :raises FileNotFoundError: If the ZIP file does not exist.
        :raises zipfile.BadZipFile: If the file is not a valid ZIP archive.
        """
        zip_path_obj = Path(zip_path)
        if not zip_path_obj.exists():
            raise FileNotFoundError(f"ZIP file not found: {zip_path}")

        output_dir_obj = Path(output_dir)
        output_dir_obj.mkdir(parents=True, exist_ok=True)

        extracted_files = []

        with zipfile.ZipFile(zip_path, 'r') as zip_ref:
            for file_info in zip_ref.namelist():
                if file_info.endswith('.5gm') and not file_info.endswith('/'):
                    filename = Path(file_info).name
                    file_content = zip_ref.read(file_info)
                    extracted_path = output_dir_obj / filename

                    with open(extracted_path, 'wb') as output_file:
                        output_file.write(file_content)

                    extracted_files.append(str(extracted_path))

        logger.debug(f"Extracted {len(extracted_files)} .5gm file(s) from {zip_path} to {output_dir}")
        return extracted_files

    @staticmethod
    def merge_json_files(input_files: List[str], output_path: str, json_format: str = "json") -> str:
        """
        Merge multiple JSON files into a single output file.

        :param input_files: List of paths to input JSON files.
        :param output_path: The path to the output merged JSON file.
        :param json_format: The format of the JSON files. Supported: 'json' (array format) or 'ndjson' (newline-delimited).

        :return: Path to the output file.

        :raises FileNotFoundError: If any input file does not exist.
        :raises ValueError: If json_format is not 'json' or 'ndjson'.
        :raises json.JSONDecodeError: If any input file contains invalid JSON.
        """
        if json_format not in ['json', 'ndjson']:
            raise ValueError(f"Unsupported json_format: {json_format}. Must be 'json' or 'ndjson'")

        output_path_obj = Path(output_path)
        output_path_obj.parent.mkdir(parents=True, exist_ok=True)

        for file_path in input_files:
            file_path_obj = Path(file_path)
            if not file_path_obj.exists():
                raise FileNotFoundError(f"Input file not found: {file_path}")

        logger.debug(f"Merging {len(input_files)} JSON file(s) to {output_path} (format: {json_format})")
        if json_format == "ndjson":
            Decoder._write_merged_ndjson(input_files, output_path)
        else:
            Decoder._write_merged_json_array(input_files, output_path)

        logger.debug(f"Merged JSON files written to {output_path}")
        return output_path

    @staticmethod
    def sort_emil_log_files(log_file_paths: List[str]) -> Dict[str, List[str]]:
        """
        Group EMIL log file paths by BTS ID and sort each group by timestamp (newest first).

        :param log_file_paths: List of paths to log files (.5gm or .json with same naming).
        :return: Dict mapping BTS ID to list of file paths, each list sorted newest to oldest.
        """
        def _sort_key(file_path: str) -> str:
            parts = Path(file_path).name.split("_")
            return parts[2] if len(parts) > 2 else ""

        log_paths = {}
        for file_path in log_file_paths:
            parts = Path(file_path).name.split("_")
            bts_id = parts[0] if parts else ""
            log_paths.setdefault(bts_id, []).append(file_path)

        for paths in log_paths.values():
            paths.sort(key=_sort_key, reverse=True)

        return log_paths

    @staticmethod
    def _write_merged_ndjson(input_files: List[str], output_path: str) -> None:
        """Concatenate NDJSON files (newline-delimited lines) into one file."""
        with open(output_path, 'w', encoding='utf-8') as output_file:
            for file_path in input_files:
                with open(file_path, 'r', encoding='utf-8') as input_file:
                    for line in input_file:
                        line = line.strip()
                        if line:
                            output_file.write(line + '\n')

    @staticmethod
    def _write_merged_json_array(input_files: List[str], output_path: str) -> None:
        """Load JSON files (emil_data.rows), merge rows, write single JSON file."""
        with open(input_files[0], 'r', encoding='utf-8') as first_file:
            merged = json.load(first_file)

        for file_path in input_files[1:]:
            with open(file_path, 'r', encoding='utf-8') as input_file:
                data = json.load(input_file)
            merged['emil_data']['rows'].extend(data['emil_data']['rows'])

        with open(output_path, 'w', encoding='utf-8') as output_file:
            json.dump(merged, output_file, indent=1, ensure_ascii=False)

    def _ensure_directories_for_utf_zipped_logs(self, output_path: str) -> Tuple[Path, Path, Path]:
        """
        Create and return output directory and temporary subdirectories for UTF zipped logs processing.

        :param output_path: Path to the main output directory.
        :return: Tuple of (output_path_obj, emil_5gm_files_dir, emil_json_files_dir).
        """
        output_path_obj = Path(output_path)
        emil_5gm_files_dir = output_path_obj / "emil_5gm_logs"
        emil_json_files_dir = output_path_obj / "emil_json_files"

        output_path_obj.mkdir(parents=True, exist_ok=True)
        emil_5gm_files_dir.mkdir(parents=True, exist_ok=True)
        emil_json_files_dir.mkdir(parents=True, exist_ok=True)

        return output_path_obj, emil_5gm_files_dir, emil_json_files_dir

    def _decode_5gm_files_to_json(
        self,
        emil_5gm_files: List[str],
        emil_json_files_dir: Path,
        utf_host: str,
        utf_port: str,
        json_format: str,
    ) -> List[str]:
        """
        Decode each .5gm file to JSON or NDJSON and return list of output file paths.

        :param emil_5gm_files: List of paths to .5gm files.
        :param emil_json_files_dir: Directory for intermediate JSON files.
        :param utf_host: The UTF host address.
        :param utf_port: The UTF port number.
        :param json_format: Output format: 'json' or 'ndjson'.

        :return: List of paths to decoded JSON/NDJSON files.
        """
        logger.debug(f"Decoding {len(emil_5gm_files)} .5gm file(s) to {json_format}")
        emil_json_files = []
        for emil_5gm_file in emil_5gm_files:
            intermediate_file_path = emil_json_files_dir / (Path(emil_5gm_file).stem + ".json")
            if json_format == "ndjson":
                result_path = self.decode_emil_to_ndjson(
                    emil_5gm_file, str(intermediate_file_path), utf_host, utf_port
                )
            else:
                result_path = self.decode_emil_to_json(
                    emil_5gm_file, str(intermediate_file_path), utf_host, utf_port
                )
            emil_json_files.append(result_path)
        return emil_json_files

    def _merge_json_by_bts_id(
        self,
        json_files_by_bts_id: Dict[str, List[str]],
        output_path_obj: Path,
        file_prefix: str,
        json_format: str,
    ) -> List[str]:
        """
        Merge JSON files per BTS ID and save to output directory.

        :param json_files_by_bts_id: Dict mapping BTS ID to list of JSON file paths.
        :param output_path_obj: Output directory for merged files.
        :param file_prefix: Prefix for merged filenames.
        :param json_format: Format of JSON files: 'json' or 'ndjson'.

        :return: List of paths to merged output files.
        """
        merged_files = []
        for bts_id, json_paths in json_files_by_bts_id.items():
            logger.debug(f"Merging {json_paths} files for BTS {bts_id}")
            merged_output_path = output_path_obj / f"{file_prefix}_{bts_id}.json"
            self.merge_json_files(json_paths, str(merged_output_path), json_format)
            merged_files.append(str(merged_output_path))
            logger.debug(f"Created merged EMIL JSON file for BTS {bts_id}: {merged_output_path}")
        return merged_files

    def _remove_temporary_directories(self, *dirs: Path) -> None:
        """
        Remove temporary directories and log the operation.

        :param dirs: Paths to directories to remove.
        """
        for directory in dirs:
            shutil.rmtree(directory)
        if dirs:
            logger.debug(f"Cleaned temporary directories: {', '.join(str(d) for d in dirs)}")

    def _decode_emil_with_converter(self, input_path: str, output_path: str, utf_host: str,
                                    utf_port: str, converter_name: str, output_type: Optional[str] = None) -> None:
        """
        Helper method to decode EMIL file using EMIL converter.

        :param input_path: The path to the input EMIL file.
        :param output_path: The path to the output directory.
        :param utf_host: The UTF host address.
        :param utf_port: The UTF port number.
        :param converter_name: The name of the converter.
        :param output_type: Optional output type (e.g., 'csv').

        :return: None

        :raises Exception: If converter setup or conversion fails.
        """
        utf_info = {'host': utf_host, 'port': utf_port}

        output_path_obj = Path(output_path)

        if output_path_obj.suffix == '.json':
            final_output_dir = str(output_path_obj.parent)
            target_filename = output_path_obj.name
        else:
            final_output_dir = output_path
            target_filename = None

        output_directory = final_output_dir
        aux_dir = None
        if target_filename:
            aux_dir = Path(final_output_dir) / f"_emil_convert_tmp_{uuid.uuid4().hex[:8]}"
            aux_dir.mkdir(parents=True, exist_ok=True)
            output_directory = str(aux_dir)

        Path(output_directory).mkdir(parents=True, exist_ok=True)

        converter_params = {
            'name': converter_name,
            'file_path_pattern': input_path,
            'dcap': utf_info,
            'output_directory': output_directory
        }

        if output_type:
            converter_params['output_type'] = output_type

        self._emil_converter.create_emil_converter_for_source(**converter_params)

        setup_completed = False
        try:
            logger.debug(f"Setting up EMIL converter: {converter_name} for {input_path}")
            self._emil_converter.setup(converter_name)
            setup_completed = True
            self._emil_converter.convert(converter_name)
            logger.debug(f"Conversion completed: {converter_name}")

            if target_filename and aux_dir is not None:
                self._rename_and_move_from_aux_dir(aux_dir, final_output_dir, target_filename)
        finally:
            if setup_completed:
                self._emil_converter.teardown(converter_name)
            if aux_dir is not None and aux_dir.exists():
                try:
                    shutil.rmtree(aux_dir)
                    logger.debug(f"Removed auxiliary directory: {aux_dir}")
                except OSError as e:
                    logger.warn(f"Failed to remove auxiliary directory {aux_dir}: {e}")

    @staticmethod
    def _rename_and_move_from_aux_dir(aux_dir: Path, final_output_dir: str, target_filename: str) -> None:
        """
        Find the single JSON file in the auxiliary directory, rename it to target_filename,
        then move it to the final output directory. The caller is responsible for removing
        aux_dir (e.g. in a finally block).

        :param aux_dir: The auxiliary directory containing the converted file (single .json).
        :param final_output_dir: The directory where the file should end up.
        :param target_filename: The target filename (should include .json extension).

        :raises FileNotFoundError: If no JSON file is found in the auxiliary directory.
        """
        if not aux_dir.exists():
            raise FileNotFoundError(f"Auxiliary directory not found: {aux_dir}")

        json_files = list(aux_dir.glob('*.json'))
        if not json_files:
            raise FileNotFoundError(f"No JSON file found in auxiliary directory: {aux_dir}")

        source_file = json_files[0]
        renamed_in_aux = aux_dir / target_filename
        if source_file != renamed_in_aux:
            source_file.rename(renamed_in_aux)
            source_file = renamed_in_aux
        else:
            renamed_in_aux = source_file

        dest_file = Path(final_output_dir) / target_filename
        shutil.move(str(renamed_in_aux), str(dest_file))
